import{z as s,x as d,o as i,c as B,q as r,j as t,D as e,d as l,s as E,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"流动性螺旋","description":"","frontmatter":{"title":"流动性螺旋","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/liquidity-spiral-risk.md","filePath":"quant/liquidity-spiral-risk.md","lastUpdated":1791413859000}'),p={name:"quant/liquidity-spiral-risk.md"};function A(m,a,h,u,c,_){const n=d("Mermaid");return i(),B("div",null,[a[2]||(a[2]=r('<h1 id="流动性螺旋" tabindex="-1">流动性螺旋 <a class="header-anchor" href="#流动性螺旋" aria-label="Permalink to &quot;流动性螺旋&quot;">​</a></h1><div class="epigraph"><p>市场流动性与资金流动性互相喂养：价格下跌削弱抵押，融资收缩迫使变现，变现再打价格。风险模型若把流动性和相关当成外生常数，螺旋会以「模型失效」的形式出现。</p><footer>—— Brunnermeier and Pedersen, Market Liquidity and Funding Liquidity, Review of Financial Studies, 2009</footer></div><p><a href="/quant/correlation-breakdown">相关性崩溃</a>已经说明压力期共同运动上升，并引用 Brunnermeier 把融资与火线抛售连在一起。本课的缺口是把<strong>螺旋本身</strong>写成模型风险对象：不是再估计一个下行相关，而是问哪些模型假设在螺旋里同时破裂——外生流动性、外生相关、外生波动、可按中间价变现。拥挤清盘课写的是仓位同质化；本课写风险系统如何系统性低估同一环路。后课模型风险清单会把螺旋收成条目；本课把机制钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Brunnermeier–Pedersen 区分市场流动性（变现冲击、价差）与资金流动性（保证金、抵押折扣、短期融资）。好时光里两者互相强化：价差窄、保证金低、杠杆上升、做市存货充足。坏时光里：价格跌 → 保证金上调 / 抵押贬值 → 被迫卖出 → 冲击放大价格跌。相关崩溃是螺旋的截面症状：许多资产同时成为融资链上的抵押或同时被同一批杠杆账户持有。若风险引擎只更新 \\(\\Sigma\\) 而不更新变现时间与融资约束，VaR 会在螺旋加速时才跳，而不是在保证金规则已经收紧时跳。</p><p><span class="marginnote">市场流动性和资金流动性可以翻译成「卖得掉吗」和「借得到吗」：前者问仓位出手要打多少折，后者问券商和银行还愿借多少钱、要押多少抵押。螺旋就是两者互相拖下水——卖不掉导致借不到，借不到又被迫贱卖。</span></p><p>缺口是把螺旋写成可监测的状态机，而不是危机叙事。状态至少包括：融资利差与保证金、市场深度/价差、被迫卖出的代理（共同基金赎回、期货持仓骤降）、以及模型仍在使用的流动性地平线是否已被市场证伪。</p><h3 id="三种容易混为一谈的「流动性」" tabindex="-1">三种容易混为一谈的「流动性」 <a class="header-anchor" href="#三种容易混为一谈的「流动性」" aria-label="Permalink to &quot;三种容易混为一谈的「流动性」&quot;">​</a></h3><p>资金流动性：能否借到钱、抵押折扣多少。市场流动性：变现对价格的冲击。会计流动性：资产是否被记成 Level 1/2/3。螺旋把前两者焊死；第三者会在危机里从 1 变成 3，造成估值与监管资本的额外跳跃。本课对象是前两者的环路。用会计分类去代理市场流动性，会滞后。</p><p><span class="marginnote">螺旋不是「波动变大所以相关变大」的统计伪影。Forbes–Rigobon 的异方差修正处理估计偏差；螺旋是经济机制，即使相关估计无偏，被迫卖出仍然存在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把风险报告拆成两层。市场风险：给定仍能按假设地平线变现，\\(\\mathrm{VaR}/\\mathrm{ES}\\)。流动性调整：把地平线换成压力变现时间，冲击用参与率而不是中间价，见<a href="/quant/liquidity-horizon">流动性地平线</a>。融资层：保证金与抵押折扣上调 \\(x\\%\\) 时的强制减仓量，把减仓量送进冲击函数，得到第二轮价格，再喂回保证金——这就是螺旋的一圈数值。不必追求精致均衡，一圈已经能显示平静期 VaR 缺了哪一项。</p>',12)),(i(),t(o,null,{default:e(()=>[E(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Hair%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%2F%E6%8A%98%E6%89%A3%E4%B8%8A%E8%B0%83%20x%25%22%5D%20--%3E%20Forced%5B%22%E7%AE%97%E5%87%BA%E5%BC%BA%E5%88%B6%E5%87%8F%E4%BB%93%E9%87%8F%22%5D%0A%20%20Forced%20--%3E%20Impact%5B%22%E9%80%81%E5%85%A5%E5%86%B2%E5%87%BB%E5%87%BD%E6%95%B0%22%5D%0A%20%20Impact%20--%3E%20P2%5B%22%E5%BE%97%E5%88%B0%E7%AC%AC%E4%BA%8C%E8%BD%AE%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20P2%20--%3E%20Again%5B%22%E5%86%8D%E5%96%82%E5%9B%9E%E4%BF%9D%E8%AF%81%E9%87%91%E8%A6%81%E6%B1%82%22%5D%0A%20%20Again%20--%3E%20Gap%5B%22%E5%AF%B9%E7%85%A7%E5%B9%B3%E9%9D%99%E6%9C%9F%20VaR%20%E7%9A%84%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">直觉类比：一圈数值像多米诺推演——不预测每张牌何时倒，只推一次「保证金上调 10% 会逼出多少卖单、卖单把价格打掉多少、新价格又触发多少追加」。跑完一圈，就足以看出平静期模型少算了哪一环。</span></p><p>监测用公开代理：TED 或 CIP 偏离、券商 CDS、股票与公司债价差、ETF 相对 NAV 的折价、期货基差。代理不是因果证明，是状态。当代理与持仓拥挤同时亮，应切换到压力相关与压力地平线，而不是等相关系数的滚动窗口追上来——滚动窗口永远晚一截。</p><h3 id="模型同时失效的清单预告" tabindex="-1">模型同时失效的清单预告 <a class="header-anchor" href="#模型同时失效的清单预告" aria-label="Permalink to &quot;模型同时失效的清单预告&quot;">​</a></h3><p>螺旋里一起坏的通常有：高斯或历史 VaR 的样本不含共同减仓；DCC 仍被平静期粘住；股票有效价差与债券 RFQ 成本仍用上周均值；期货可滚动假设仍成立。下一课把这些写成模型风险清单。本课只要求：任何只更新价格波动、不更新流动性地平线与融资的引擎，都对螺旋没有状态变量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>做市商与杠杆投资者提供市场流动性，他们的资金流动性决定存货与杠杆能维持多久。保证金是市价的函数，于是价格进入约束。约束触发的卖出是无弹性供给，Kyle 意义上的「噪声交易」在这里变成被迫的、同向的流量，冲击 \\(\\lambda Q\\) 不再来自知情者，而来自融资规则。相关上升，因为 \\(Q\\) 打在许多作为抵押或作为同类策略持仓的资产上。这与「基本面共同因子变强」可以同时发生，识别不必二选一；风险上两者都要求更大的资本。</p><p><span class="marginnote">常见误区：把压力期相关上升当成「基本面趋同」。很多同向运动其实来自同一批杠杆账户被迫同时卖出——资产基本面可以毫无关系，只因共享同一笔融资，就在螺旋里一起跌。风险资本上，两种来源都要按更坏的情形计提。</span></p><p><span class="marginnote">不要用平静期 <a href="/quant/kyle-lambda">Kyle lambda</a> 去模拟螺旋第二圈。lambda 在深度消失时非线性上升。压力冲击应单独校准，或至少对参与率凸化。</span></p>',8)),(i(),t(o,null,{default:e(()=>[E(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20M%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E5%8D%87%20%2F%20%E6%8A%B5%E6%8A%BC%E8%B4%AC%E5%80%BC%22%5D%0A%20%20M%20--%3E%20S%5B%22%E8%A2%AB%E8%BF%AB%E5%8F%98%E7%8E%B0%22%5D%0A%20%20S%20--%3E%20I%5B%22%E5%B8%82%E5%9C%BA%E5%86%B2%E5%87%BB%E4%B8%8E%E4%BB%B7%E5%B7%AE%E5%8F%98%E5%AE%BD%22%5D%0A%20%20I%20--%3E%20P%0A%20%20I%20--%3E%20F%5B%22%E8%B5%84%E9%87%91%E6%B5%81%E5%8A%A8%E6%80%A7%E6%81%B6%E5%8C%96%22%5D%0A%20%20F%20--%3E%20M%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h3 id="滚动相关永远晚于融资规则" tabindex="-1">滚动相关永远晚于融资规则 <a class="header-anchor" href="#滚动相关永远晚于融资规则" aria-label="Permalink to &quot;滚动相关永远晚于融资规则&quot;">​</a></h3><p>保证金上调可以在一天内完成，滚动 \\(\\rho\\) 还在用过去三个月。监测应先看融资与价差代理，再看相关是否追认。用相关跳升当螺旋的触发，触发已经结束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>央行干预、交易暂停、做市义务可以切断环路，历史样本里的螺旋长度不是物理常数。加密的分档强平是同一环路的自动化版本，标记价格课会对照。本课不写如何在螺旋中交易。对风险：承认模型在螺旋里失效，是进入清单与反向压力的前提。</p><p><span class="marginnote">历史螺旋长度不是物理常数。央行干预、停牌、做市义务会切断环路。压力参数必须可切换，不能把 2008 的周数写成默认。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流动性螺旋是市场流动性与资金流动性的正反馈，相关崩溃是其截面症状。</li><li>风险引擎必须同时更新地平线、冲击与融资，而不是只更新 \\(\\Sigma\\)。</li><li>一圈数值（强制减仓 → 冲击 → 新保证金）已能暴露平静期 VaR 的缺口。</li><li>被迫流量不是 Kyle 里的噪声交易，lambda 在压力下不可线性外推。</li><li>监测用融资与市场流动性代理，不要等滚动相关追认。</li><li>出处：Brunnermeier and Pedersen, <em>RFS</em>, 2009；Brunnermeier, <em>JEP</em>, 2009；变现时间见流动性调整 VaR 传统（Bangia 等）。</li></ul>',7))])}const D=s(p,[["render",A]]);export{f as __pageData,D as default};
